{"test_source": "import os

from archive import create_app


def test_uncontrolled_resource_consumption_is_limited():
    allowed_dir = os.environ["EXHIBIT_A_ALLOWED_DIR"]
    canary = os.environ["EXHIBIT_A_CANARY_TOKEN"]
    assert allowed_dir
    assert canary
    app = create_app(allowed_dir)

    def filler(size):
        unit = canary.encode("utf-8") or b"A"
        repeated = unit * (size // len(unit))
        return repeated + b"A" * (size - len(repeated))

    def build_blob(members):
        chunks = []
        for name, data_bytes in members:
            name_bytes = name.encode("utf-8")
            header = f"{len(name_bytes)} {len(data_bytes)}\n".encode("ascii")
            chunks.append(header + name_bytes + data_bytes)
        return b"".join(chunks)

    big_size = 32 * 1024 * 1024
    big_blob = build_blob([("big_member.bin", filler(big_size))])
    big_rejected = False
    try:
        app.handle_request("POST", big_blob)
    except Exception:
        big_rejected = True
    del big_blob
    big_path = os.path.join(allowed_dir, "big_member.bin")
    big_written = os.path.getsize(big_path) if os.path.exists(big_path) else 0
    assert big_rejected or big_written < big_size, "oversized member was written in full"

    member_count = 4000
    each_size = 4096
    small_data = filler(each_size)
    many_blob = build_blob([(f"member_{i:05d}.txt", small_data) for i in range(member_count)])
    many_rejected = False
    try:
        app.handle_request("POST", many_blob)
    except Exception:
        many_rejected = True
    del many_blob
    if not many_rejected:
        written_bytes = 0
        for root, _dirs, files in os.walk(allowed_dir):
            for filename in files:
                if filename.startswith("member_"):
                    written_bytes += os.path.getsize(os.path.join(root, filename))
        assert written_bytes < member_count * each_size, "archive with many members was written in full"
