{"test_source": "import os
import signal

import pytest

from archive import create_app


def test_malformed_negative_length_archive_does_not_hang_or_crash():
    allowed_dir = os.environ["EXHIBIT_A_ALLOWED_DIR"]
    canary_token = os.environ["EXHIBIT_A_CANARY_TOKEN"]
    assert allowed_dir
    assert canary_token
    assert os.path.isdir(allowed_dir)

    app = create_app(allowed_dir)

    class _Timeout(Exception):
        pass

    def _handler(signum, frame):
        raise _Timeout()

    previous_handler = signal.signal(signal.SIGALRM, _handler)

    def call(blob):
        signal.setitimer(signal.ITIMER_REAL, 1.5)
        try:
            return app.handle_request("POST", blob)
        finally:
            signal.setitimer(signal.ITIMER_REAL, 0)

    try:
        # The header is 5 bytes; -5 + 0 == -5, so a parser trusting these
        # lengths makes no forward progress and re-parses it forever.
        try:
            result = call(b"-5 0\n")
        except _Timeout:
            pytest.fail("handle_request hung on negative archive lengths (DoS)")
        except Exception as exc:
            pytest.fail(f"handle_request raised uncaught {type(exc).__name__} on negative lengths: {exc}")

        if isinstance(result, (list, tuple)):
            assert len(result) == 0, f"negative-length archive should write no files, got {result!r}"
        else:
            assert result is None or isinstance(result, (str, bytes)), f"unexpected result {result!r}"
        assert canary_token not in str(result)

        for blob in (b"-1 -1\n", b"bad header\n", b"no-newline", b"1 1\n\xff\xff"):
            try:
                outcome = call(blob)
            except _Timeout:
                pytest.fail(f"handle_request hung on malformed archive {blob!r}")
            except Exception as exc:
                pytest.fail(f"handle_request raised uncaught {type(exc).__name__} on malformed archive {blob!r}: {exc}")
            if isinstance(outcome, (list, tuple)):
                assert len(outcome) == 0, f"malformed archive {blob!r} should write no files, got {outcome!r}"
            assert canary_token not in str(outcome)
    finally:
        signal.setitimer(signal.ITIMER_REAL, 0)
        signal.signal(signal.SIGALRM, previous_handler)
